import{_ as e,o,c as i,ag as t}from"./chunks/framework.D9ghT4bC.js";const u=JSON.parse('{"title":"CoeHarMod 模组介绍","description":"","frontmatter":{"title":"CoeHarMod 模组介绍"},"headers":[],"relativePath":"zh/Community/Mods/CoeHarMod/index.md","filePath":"zh/Community/Mods/CoeHarMod/index.md"}'),l={name:"zh/Community/Mods/CoeHarMod/index.md"};function r(d,a,n,s,c,h){return o(),i("div",null,[...a[0]||(a[0]=[t('<h2 id="关于-coeharmod" tabindex="-1">关于 CoeHarMod <a class="header-anchor" href="#关于-coeharmod" aria-label="Permalink to &quot;关于 CoeHarMod&quot;">​</a></h2><p>CoeHarMod（和合共生）是一个致力于优化和扩展 Unciv 游戏体验的大型规则集模组。</p><h3 id="核心理念" tabindex="-1">核心理念 <a class="header-anchor" href="#核心理念" aria-label="Permalink to &quot;核心理念&quot;">​</a></h3><blockquote><p>&quot;和合共生，万物各得其和以生，各得其养以成&quot;</p></blockquote><p>本模组致力于在保持游戏平衡性的基础上，为玩家提供更加丰富和多样化的游戏体验。</p><h3 id="快速链接" tabindex="-1">快速链接 <a class="header-anchor" href="#快速链接" aria-label="Permalink to &quot;快速链接&quot;">​</a></h3><div class="tip custom-block"><p class="custom-block-title">模组资源</p><ul><li><a href="https://github.com/AutumnPizazz/CoeHarMod" target="_blank" rel="noreferrer">GitHub 仓库</a></li><li><a href="/Unciv/zh/Community/Mods/CoeHarMod/更新日志/">更新日志</a></li><li><a href="/Unciv/zh/Community/Mods/CoeHarMod/更新日志/更新计划.html">更新计划</a></li></ul></div><h3 id="加入社区" tabindex="-1">加入社区 <a class="header-anchor" href="#加入社区" aria-label="Permalink to &quot;加入社区&quot;">​</a></h3><p>如果您对模组有任何建议或问题，欢迎加入我们的 QQ 群：</p><p><a href="https://qm.qq.com/q/amwSqibPmo" target="_blank" rel="noreferrer"><img src="https://img.shields.io/badge/QQ%E7%BE%A4-%E7%82%B9%E5%87%BB%E5%8A%A0%E5%85%A5-green?logo=tencent-qq" alt="QQ 群"></a></p><h3 id="安装指南" tabindex="-1">安装指南 <a class="header-anchor" href="#安装指南" aria-label="Permalink to &quot;安装指南&quot;">​</a></h3><ol><li>下载最新版模组文件</li><li>将模组文件夹放入游戏 <code>mods/</code> 目录</li><li>在游戏设置中启用 CoeHarMod</li><li>开始新游戏即可体验</li></ol><div class="warning custom-block"><p class="custom-block-title">注意</p><ul><li>模组仅支持新游戏，无法兼容已有存档</li><li>建议在标准速度下游玩以获得最佳体验</li><li>部分功能需要开启特定模式（如秘密结社模式）</li></ul></div><h3 id="致谢" tabindex="-1">致谢 <a class="header-anchor" href="#致谢" aria-label="Permalink to &quot;致谢&quot;">​</a></h3><p>感谢所有为模组做出贡献的玩家和开发者！</p><p>特别感谢：</p><ul><li>Unciv 开发团队提供的优秀游戏平台</li><li>所有参与测试和反馈的玩家</li><li>Unciv 中文社区的支持</li></ul>',17)])])}const p=e(l,[["render",r]]);export{u as __pageData,p as default};
